#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

const int64 MOD = 998244353;

int64 modPow(int64 a, int64 e) {
    int64 result = 1;
    while (e > 0) {
        if (e & 1) result = result * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    int64 l;
    cin >> n >> k >> l;

    int limit = 2 * n + 1;
    vector<int64> fact(limit + 1), invFact(limit + 1), pow2(n + 1);

    fact[0] = 1;
    for (int i = 1; i <= limit; ++i)
        fact[i] = fact[i - 1] * i % MOD;

    invFact[limit] = modPow(fact[limit], MOD - 2);
    for (int i = limit; i >= 1; --i)
        invFact[i - 1] = invFact[i] * i % MOD;

    pow2[0] = 1;
    for (int i = 1; i <= n; ++i)
        pow2[i] = pow2[i - 1] * 2 % MOD;

    auto C = [&](int a, int b) -> int64 {
        if (b < 0 || b > a) return 0;
        return fact[a] * invFact[b] % MOD * invFact[a - b] % MOD;
    };

    int64 answer = 0;

    for (int a = k; a <= n; ++a) {
        int64 beta = fact[a] * fact[a] % MOD * invFact[2 * a + 1] % MOD;

        int64 term = C(n, a);
        term = term * C(a - 1, k - 1) % MOD;
        term = term * pow2[a] % MOD;
        term = term * beta % MOD;

        if ((a - k) & 1)
            answer = (answer - term + MOD) % MOD;
        else
            answer = (answer + term) % MOD;
    }

    answer = answer * (l % MOD) % MOD;
    cout << answer << '\n';

    return 0;
}

